// Part 7: Scripting and scheduling, units 59-66. See materials/curriculum.md and materials/objectives/.
// p7Fixture() is the home folder plus small scripts to read, run and fix, and the files they work on.
function p7Fixture() {
  const fx = homeFixture();
  fx.dirs.push('/home/user/bin');
  const add = (p, lines, mode = 0o755) => fx.files.push([p.startsWith('/') ? p : `/home/user/${p}`, { content: lines.join('\n') + '\n', mode }]);
  add('greet.sh', ['#!/bin/bash', '# Says hello to the name in the first argument', 'name=${1:-world}', 'echo "Hello, $name!"'], 0o644);
  add('args.sh', ['#!/bin/bash', 'echo "script: $0"', 'echo "count: $#"', 'echo "first: $1"', 'echo "all: $@"']);
  add('check.sh', ['#!/bin/bash', 'if [ $# -ne 1 ]; then', '  echo "usage: $0 FILE" >&2', '  exit 1', 'fi', 'if [ -f "$1" ]; then', '  echo "$1 is a file"', 'elif [ -d "$1" ]; then', '  echo "$1 is a folder"', 'else', '  echo "$1 does not exist"', '  exit 2', 'fi']);
  add('service.sh', ['#!/bin/bash', 'case "$1" in', '  start) echo "Starting web";;', '  stop) echo "Stopping web";;', '  restart|reload) echo "Restarting web";;', '  *) echo "usage: $0 start|stop|restart"; exit 1;;', 'esac']);
  add('lib.sh', ['# Functions to load with: source lib.sh', 'square() {', '  echo $(( $1 * $1 ))', '}', 'greet() {', '  local name=$1', '  echo "Hi $name"', '}'], 0o644);
  add('backup.sh', ['#!/bin/bash', '# Copies every .txt file into a folder (backup if no name is given)', 'dest=${1:-backup}', 'mkdir -p "$dest"', 'count=0', 'for f in *.txt; do', '  cp "$f" "$dest/"', '  count=$((count + 1))', 'done', 'echo "Saved $count files to $dest"']);
  add('report.sh', ['#!/bin/bash', '# Counts each level in a log file', 'log=${1:-logs/app.log}', 'if [ ! -f "$log" ]; then', '  echo "no such log: $log" >&2', '  exit 1', 'fi', 'for level in INFO WARN ERROR; do', '  echo "$level: $(grep -c "$level" "$log")"', 'done']);
  add('people.sh', ['#!/bin/bash', '# Says where everyone in people.csv lives', 'tail -n +2 people.csv | while IFS=, read name city age; do', '  echo "$name ($age) lives in $city"', 'done']);
  add('users.sh', ['#!/bin/bash', '# Lists the users whose shell is bash', 'total=0', 'while IFS=: read user x uid gid desc home shell; do', '  if [ "$shell" = /bin/bash ]; then', '    echo "$user ($uid)"', '    total=$((total + 1))', '  fi', 'done < /etc/passwd', 'echo "$total users use bash"']);
  add('bin/hello', ['#!/bin/bash', 'echo "hello from ~/bin"']);
  add('.profile', ['# ~/.profile: read by login shells', 'export EDITOR=nano', 'if [ -f "$HOME/.bashrc" ]; then', '  . "$HOME/.bashrc"', 'fi'], 0o644);
  add('numbers.txt', ['4', '9', '2', '7'], 0o644);
  add('servers.txt', ['web1', 'web2', 'db1'], 0o644);
  add('/etc/passwd', ['root:x:0:0:root:/root:/bin/bash', 'daemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin', 'www-data:x:33:33:www-data:/var/www:/usr/sbin/nologin', 'user:x:1000:1000:User:/home/user:/bin/bash', 'dana:x:1001:1001:Dana Levi:/home/dana:/bin/bash', 'omer:x:1002:1002::/home/omer:/bin/zsh'], 0o644);
  return fx;
}
const p7Out = (cmd, setup = []) => { const sh = new Shell(p7Fixture()); for (const c of setup) sh.run(c); const r = sh.run(cmd); return r.out + r.err; };
const p7Shown = (log, cmd, setup) => { const want = p7Out(cmd, setup).trim(); return !!want && log.some(l => l.out.trim() === want); };
const p7Mode = (sh, p) => sh.meta(p)?.mode & 0o7777;
const P7_SERVER = T('הפלט הוקלט על שרת Ubuntu אמיתי. מה הודפס?', 'This was recorded on a real Ubuntu server. What was printed?');
const p7Root = (cmd, extra = []) => [cmd, `sudo ${cmd}`, ...extra];

